import {GEAR,SUPPLIES} from './data.js';
let sequence=0;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bell=(x,y)=>`<g class="bell-swing" transform="translate(${x} ${y})"><path d="M-7-2Q-9-14-2-15Q4-14 3-3L-7-2ZM5-2Q3-14 10-15Q16-14 15-3L5-2Z" fill="#ceb877" stroke="#ead8a0" stroke-width=".8"/><circle cx="-2" cy="-1" r="1.7" fill="#f4e2aa"/><circle cx="10" cy="-1" r="1.7" fill="#f4e2aa"/><path d="M-3-16l7-7 7 7" stroke="#a0ad8b" fill="none"/></g>`;
export function indicatorArt(i){
 let body=i.style==='feeder'?`<g transform="translate(160 87) scale(2.7)">${bell(0,0)}<rect x="-4" y="-32" width="17" height="7" rx="3" fill="#737e5c" stroke="#b5c698"/>${i.id.includes('smart')?'<circle cx="5" cy="-28" r="2" fill="#d5ef8a"/>':''}</g>`:i.style==='dobber'?`<path d="M160 118v-77" stroke="#c7cbab" stroke-width="3"/><path d="M160 42v-24" stroke="${i.id.includes('glow')?'#d9ff86':'#edbb74'}" stroke-width="5" stroke-linecap="round" style="filter:drop-shadow(0 0 7px #c8f784)"/><ellipse cx="160" cy="86" rx="10" ry="27" fill="#776b42" stroke="#c7b87d"/><path d="M151 78h18" stroke="#d1ab70" stroke-width="5"/><ellipse cx="160" cy="121" rx="44" ry="5" stroke="#78a899" opacity=".35"/>`:`<path d="M159 115v-18M142 23v20m0-20h-7m7 20h36" stroke="#b4bd9e" stroke-width="3"/><rect x="128" y="40" width="65" height="64" rx="10" fill="#3f5041" stroke="#aab89c"/><path d="M139 41v-10m44 10v-10M136 32q24 24 50 0" stroke="#d5d9bc" stroke-width="4" fill="none"/><circle cx="160" cy="58" r="5" fill="#d5df93" style="filter:drop-shadow(0 0 5px #c5ea8b)"/><circle cx="146" cy="83" r="7" fill="#7c8d6a" stroke="#bbbf9e"/><circle cx="176" cy="83" r="7" fill="#7c8d6a" stroke="#bbbf9e"/>${i.id.includes('receiver')?'<rect x="210" y="48" width="27" height="53" rx="5" fill="#314a3a" stroke="#a1b28c"/><path d="M216 48V26" stroke="#a1b28c"/><circle cx="224" cy="61" r="3" fill="#cbe799"/>':''}`;
 return `<svg viewBox="0 0 320 140" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(i.name)}"><ellipse cx="160" cy="124" rx="70" ry="6" fill="#07180e" opacity=".4"/>${body}</svg>`;
}
export function rodArt(r,{index=0,editor=false}={}){
 const id='rod-viz-'+(++sequence),ind=GEAR.find(g=>g.id===r.indicator),bait=SUPPLIES.find(b=>b.id===r.bait),float=r.style==='dobber',carp=r.style==='karper',tip=float?'#d6be7b':r.style==='feeder'?'#d6c387':'#b4bca5';
 const part=(name,body)=>editor?`<g class="visual-part" data-visual-part="${name}" data-visual-index="${index}" role="button" tabindex="0" aria-label="${name} aanpassen">${body}</g>`:body;
 const end=float?'M208 79Q238 65 260 55':carp?'M208 79Q270 61 316 73':'M208 79Q257 58 311 61';
 const equipment=GEAR.find(g=>g.id===r.rod),reelGear=GEAR.find(g=>g.id===r.reel),lineGear=GEAR.find(g=>g.id===r.line),hookGear=GEAR.find(g=>g.id===r.hook),premium=(equipment?.power||1)>2,rodFinish=premium?'#a3b9b0':'#a6b498',spoolFinish=(reelGear?.power||1)>2?'#b3bbba':'#52614b';
 const handle=`<path d="M35 184L95 147" stroke="#0a150e" stroke-width="10" stroke-linecap="round"/><path d="M37 181L78 156" stroke="#b69c70" stroke-width="8" stroke-linecap="round"/><path d="M39 178l4 7m3-11 4 7m3-11 4 7m3-11 4 7m3-11 4 7" stroke="#7d7150" stroke-width="1"/><path d="M80 156L208 79" stroke="#172d20" stroke-width="6"/><path d="M80 153L208 77" stroke="${rodFinish}" stroke-width="${premium?1.7:1.2}"/><path class="live-tip tip-shadow" d="${end}" stroke="#0a170e" stroke-width="${carp?4.7:3.8}" fill="none"/><path class="live-tip tip-highlight" d="${end}" stroke="${tip}" stroke-width="${carp?1.3:1.7}" fill="none"/><g fill="none" stroke="#c9cbae" stroke-width="1"><ellipse cx="125" cy="133" rx="3.5" ry="2" transform="rotate(-30 125 133)"/><ellipse cx="168" cy="107" rx="3" ry="1.7" transform="rotate(-30 168 107)"/><ellipse cx="207" cy="84" rx="2.6" ry="1.7"/></g>`;
 const reel=`<path d="M94 149l2 12 13 9" fill="none" stroke="#b1b89d" stroke-width="3"/><g class="reel-spool"><circle cx="104" cy="167" r="12" fill="${spoolFinish}" stroke="#d0c8a0" stroke-width="1.5"/><circle cx="104" cy="167" r="8" fill="#293f30" stroke="#c6cbb2"/><path d="M104 158v18m-8-9h16m-13-6 10 12m-11-2 11-8" stroke="#8d9b77" stroke-width="1"/><circle cx="104" cy="167" r="2" fill="#d7cfa9"/></g><path d="M111 171l10 8 10-5" stroke="#a4b192" stroke-width="2" fill="none"/><ellipse cx="133" cy="173" rx="5" ry="2.6" fill="#bda976"/><path d="M92 166q-7-27 16-14" stroke="#d5d8bc" stroke-width="1" fill="none"/>`;
 let signal='';if(r.style==='feeder'&&ind)signal=bell(235,66)+(ind.id.includes('smart')?'<circle class="signal-led" cx="233" cy="61" r="3.5" fill="#d4ed8c"/>':'');
 if(carp||r.style==='zee')signal=`<path d="M186 132v65m-7 0h14M181 130l5 5 6-5" stroke="#899b7b" stroke-width="2"/>${ind?'<rect x="176" y="122" width="21" height="22" rx="4" fill="#4c6047" stroke="#a8bc8b"/><circle class="signal-led" cx="186" cy="128" r="3" fill="#d4ec90"/><path d="M182 137h8" stroke="#253a29"/>':''}`;
 const floatBody=`<g class="float-assembly ${ind?.id==='float_glow'?'float-glow':''}"><path d="M347 139v23" stroke="#bec4a3" stroke-width="1.5"/><ellipse cx="347" cy="127" rx="7" ry="20" fill="#5e6d44" stroke="#9ca475"/><path d="M347 108V76" stroke="#d2cf9d" stroke-width="3"/><path class="float-tip" d="M347 85V63" stroke="${ind?.id==='float_glow'?'#d4ff84':ind?'#f1ba6b':'#d59171'}" stroke-width="4.5" stroke-linecap="round"/><path d="M341 119h12" stroke="#b49c67" stroke-width="4"/></g>`;
 const terminal=r.style==='feeder'?`<rect x="307" y="163" width="19" height="25" rx="3" fill="#6e7d57" stroke="#b8c599"/><path d="M308 170h17m-17 7h17m-17 6h17m-12-20v25m6-25v25" stroke="#afbd91" stroke-width=".7"/><path d="M316 160v-6m0 35q19 0 26-10" stroke="#c3d1ae" stroke-width=".8" fill="none"/>`:r.style==='karper'?`<path d="M314 157q-16 23 0 29q16-6 0-29Z" fill="#8c9877" stroke="#b5c3a0"/><path d="M314 154v-4m0 38q20 5 31-11" stroke="#c3d1ae" stroke-width=".8" fill="none"/>`:`<path d="M312 152v35q20 7 32-10" stroke="#c3d1ae" stroke-width=".8" fill="none"/><circle cx="312" cy="163" r="3" fill="#a8b394"/><circle cx="312" cy="174" r="2" fill="#a8b394"/>`;
 return `<svg class="rod-visual style-${r.style} ${editor?'is-editor':''}" viewBox="0 0 420 225" xmlns="http://www.w3.org/2000/svg" aria-label="${r.style==='feeder'?'Feeder met buigende quivertop':carp?'Karperhengel met zichtbare vrijloopmolen':float?'Matchhengel met goed zichtbare dobber':'Zeehengel met lijnratel'}" role="img"><defs><linearGradient id="${id}" x2="0" y2="1"><stop stop-color="#91b29b" stop-opacity=".02"/><stop offset="1" stop-color="#91b29b" stop-opacity=".12"/></linearGradient></defs><rect width="420" height="225" fill="url(#${id})"/><path d="M0 142q53-7 105 0t105 0t105 0t105 0v83H0Z" fill="#2c5950" opacity=".17"/><g stroke="#7eab9b" opacity=".2" stroke-width="1"><path d="M12 153h36m77-7h36m27 12h48m60-8h29m42-2h38M25 189h43m59 8h31m-4-27h37m-2 39h35"/></g>${part('line',`<path class="live-line" d="M${float?'260 55Q308 80 347 109':carp?'316 73Q338 107 363 139':'311 61Q341 96 366 139'}" stroke="#c2d6b9" stroke-width="${Math.min(1.6,.6+Math.log2(lineGear?.strength||3)*.12)}" opacity=".6" fill="none"/>`)}${part('rod',handle)}${part('reel',reel)}${part('indicator',signal||'<path d="M220 73l5 3" stroke="#adbd96" stroke-width="2"/>')}${float?part('terminal',floatBody):'<ellipse class="bite-ripple" cx="365" cy="140" rx="19" ry="4" fill="none" stroke="#c0d9af" opacity=".25"/>'}<path d="M16 213h122" stroke="#557248" stroke-width="3" opacity=".3"/>${editor?`<g><rect x="282" y="143" width="125" height="71" rx="9" fill="#11271b" stroke="#b5ca952b"/><text x="293" y="155" font-family="Arial,sans-serif" font-size="6" fill="#7f9e70" letter-spacing="1.2">JE MONTAGE</text>${part('terminal',terminal)}${part('hook',`<g transform="translate(343 180) scale(${.75+Math.min(1,Math.max(0,16-(hookGear?.size||0))/20)}) translate(-343 -180)"><path d="M348 161v22a7 7 0 0 1-14 0v-4l4 5" fill="none" stroke="#c4ccb1" stroke-width="1.7"/></g>`)}${part('bait',`<ellipse cx="351" cy="192" rx="5" ry="4" fill="${bait?.color||'#ccb889'}"/><path d="M347 186l6 4" stroke="#b1bd92" stroke-width=".8"/>`)}</g>`:''}<g class="strike-flash" opacity="0"><circle cx="286" cy="55" r="18" fill="#c4df8c" opacity=".08"/><path d="M280 55l4 4 8-10" stroke="#d2eda2" stroke-width="2" fill="none"/></g></svg>`;
}
export function sceneRods(rods){return `<g class="scene-rods">${rods.slice(0,6).map((r,i)=>{const n=rods.length,x=350+i*34,y=360,tx=x-55+(i-(n-1)/2)*13,ty=238;return `<g data-scene-rod="${i}" data-phase="waiting" style="--i:${i}"><path d="M${x-3} ${y+4}L${x+26} ${y-32}" stroke="#0f2818" stroke-width="7" stroke-linecap="round"/><path d="M${x} ${y}L${x+29} ${y-35}" stroke="#ad9368" stroke-width="5" stroke-linecap="round"/><path d="M${x+28} ${y-35}L${tx+25} ${ty+42}" stroke="#122d20" stroke-width="4"/><path d="M${x+28} ${y-35}L${tx+25} ${ty+42}" stroke="#bbc4a4" stroke-width=".8"/><path class="scene-tip" d="M${tx+25} ${ty+42}Q${tx+5} ${ty+10} ${tx} ${ty}" data-tip-x="${tx}" data-tip-y="${ty}" stroke="${r.style==='feeder'?'#e0c583':'#b6c3a5'}" stroke-width="2" fill="none"/><circle cx="${x+11}" cy="${y-6}" r="6" fill="#354e38" stroke="#c5c79c"/><path d="M${x+17} ${y-43}v37" stroke="#758963" stroke-width="2"/><path d="M${tx} ${ty}q20 12 31 37" stroke="#dde0bd" stroke-width=".6" opacity=".5" fill="none"/>${r.style==='dobber'?`<g class="scene-float"><path d="M${tx+31} ${ty+40}v-14" stroke="${r.indicator?'#d9f78c':'#cb9e6d'}" stroke-width="3"/><ellipse cx="${tx+31}" cy="${ty+42}" rx="11" ry="2.5" stroke="#c3d7ac" opacity=".4" fill="none"/></g>`:''}</g>`;}).join('')}</g>`;}
export function paintRod(svg,rt,now,reduced=false){
 const phase=rt?.phase||'waiting',live=['bite','rescue'].includes(phase),nibble=phase==='nibble',landed=phase==='landed';
 if(svg.dataset.phase!==phase)svg.dataset.phase=phase;
 const wave=reduced?.6:(.5+.5*Math.sin(now/110)),amp=live?23+wave*17:nibble?3+wave*8:landed?8:0,carp=svg.classList.contains('style-karper'),float=svg.classList.contains('style-dobber');
 const d=float?'M208 79Q238 65 260 55':carp?`M208 79Q269 ${61+amp*.35} ${316-amp*.22} ${73+amp*.65}`:`M208 79Q263 ${58+amp*.18} ${311-amp*.36} ${61+amp}`;
 svg.querySelectorAll('.live-tip').forEach(p=>p.setAttribute('d',d));
 const line=svg.querySelector('.live-line');if(line&&!float)line.setAttribute('d',carp?`M${316-amp*.22} ${73+amp*.65}Q338 107 363 139`:`M${311-amp*.36} ${61+amp}Q341 112 366 139`);
 const assembly=svg.querySelector('.float-assembly');if(assembly)assembly.setAttribute('transform',`translate(${nibble&&!reduced?Math.sin(now/140)*2:0} ${live?27+wave*5:nibble?wave*6:0})`);
 const swing=svg.querySelector('.bell-swing');if(swing)swing.style.rotate=(live?(reduced?12:Math.sin(now/65)*19):nibble?(reduced?4:Math.sin(now/100)*7):0)+'deg';
}
export function paintSceneRod(g,rt,now,reduced=false){const phase=rt?.phase||'waiting';g.dataset.phase=phase;const tip=g.querySelector('.scene-tip');if(tip){const x=Number(tip.dataset.tipX),y=Number(tip.dataset.tipY),amp=['bite','rescue'].includes(phase)?13+(reduced?4:Math.sin(now/115)*6):phase==='nibble'?(reduced?2:Math.sin(now/105)*4):0;tip.setAttribute('d',`M${x+25} ${y+42}Q${x+5} ${y+10} ${x+amp*.25} ${y+amp}`);}}
